        b.errors.append((None, f"{fname}: Error parsing configuration file: \"could not parse %{{file}} as a book file.\"\nMaybe you meant to run crowbook with the --single argument?\n")); return b
    any_valid=False
    base=path.parent
    for idx,line in enumerate(text.splitlines(),1):
        s=line.strip()
        if not s: continue
        if s.startswith('#'): continue
        m=re.match(r'^(\+|\-|\d+\.)\s+(.+)$', s)
