            marker,file=m.group(1),strip_quotes(m.group(2))
            chpath=(base/file) if hasattr(base,'__truediv__') else Path(file)
            if not Path(chpath).exists():
                b.errors.append((idx, f"{fname}:{idx}: Could not find file '{file}' for book chapter")); return b
            number=None; numbered=True
            if marker=='-': numbered=False
            elif marker.endswith('.'):
                try: number=int(marker[:-1])
                except: number=None
            b.chapters.append({'file':file,'path':str(chpath),'numbered':numbered,'number':number,'content':read_text_file(chpath)})
            any_valid=True; continue
        if ':' in s:
            k,v=s.split(':',1); k=k.strip(); v=strip_quotes(v)
