            any_valid=True; continue
        b.errors.append((idx, f"{fname}:{idx}: Error parsing configuration file: \"could not parse %{{file}} as a book file.\"\nMaybe you meant to run crowbook with the --single argument?\n")); return b
    if not any_valid:
