def inline_md(s):
    s=html.escape(s, quote=False)
    s=re.sub(r'`([^`]+)`', r'<code>\1</code>', s)
    s=re.sub(r'\*\*([^*]+)\*\*', r'<b>\1</b>', s)
    s=re.sub(r'\*([^*]+)\*', r'<em>\1</em>', s)
    s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)', lambda m: f'<a href = "{html.escape(m.group(2), quote=True)}">{m.group(1)}</a>', s)
    return s

def chapter_to_html(ch, chap_index, para_start=1, book_style=True):
    lines=ch.get('content','').splitlines()
    title=''
    body=[]; i=0; para=para_start; link=chap_index
    # use first h1 as chapter title
    while i < len(lines) and not lines[i].strip(): i+=1
    if i < len(lines) and lines[i].startswith('# '):
        title=lines[i][2:].strip(); i+=1
    else:
        title=Path(ch.get('file','')).stem
    if ch.get('numbered',True):
        num = ch.get('number') or chap_index
        body.append(f"  <h1 id = 'link-{link}'><span class = 'chapter-header'>Chapter {num}</span><br />{inline_md(title)}</h1>")
    else:
        body.append(f"  <h1 id = 'link-{link}'>{inline_md(title)}</h1>")
    in_ul=False; in_ol=False; in_code=False
    codebuf=[]
    def close_lists():
        nonlocal in_ul,in_ol
        if in_ul: body.append('</ul>'); in_ul=False
        if in_ol: body.append('</ol>'); in_ol=False
    while i < len(lines):
        line=lines[i]; st=line.strip(); i+=1
        if st.startswith('```'):
            close_lists()
            if not in_code:
                in_code=True; codebuf=[]
            else:
                body.append('<pre>'+html.escape('\n'.join(codebuf))+'\n</pre>'); in_code=False
            continue
        if in_code:
            codebuf.append(line); continue
        if not st:
            close_lists(); continue
        if st.startswith('## '):
            close_lists(); link+=1; body.append(f'<h2 id = "link-{link}">{inline_md(st[3:].strip())}</h2>'); continue
        if st.startswith('### '):
            close_lists(); link+=1; body.append(f'<h3 id = "link-{link}">{inline_md(st[4:].strip())}</h3>'); continue
        if st.startswith('>'):
            close_lists(); txt=st[1:].strip(); body.append(f'<blockquote><p id = "para-{para}">{inline_md(txt)}</p>\n</blockquote>'); para+=1; continue
        if st.startswith('- '):
            if not in_ul: close_lists(); body.append('<ul>'); in_ul=True
            body.append(f'<li><p id = "para-{para}">{inline_md(st[2:].strip())}</p>\n</li>'); para+=1; continue
        m=re.match(r'\d+\.\s+(.*)', st)
        if m:
            if not in_ol: close_lists(); body.append('<ol>'); in_ol=True
            body.append(f'<li><p id = "para-{para}">{inline_md(m.group(1).strip())}</p>\n</li>'); para+=1; continue
        close_lists(); body.append(f'<p id = "para-{para}">{inline_md(st)}</p>'); para+=1
    close_lists()
    if in_code: body.append('<pre>'+html.escape('\n'.join(codebuf))+'\n</pre>')
    return '\n'.join(body), title, para

