def latex_escape(s):
    return s.replace('\\','\\textbackslash{}').replace('&','\\&').replace('%','\\%').replace('$','\\$').replace('#','\\#').replace('_','\\_').replace('{','\\{').replace('}','\\}')

def md_to_tex_body(chapters):
    out=[]
    for ch in chapters:
        text=ch.get('content','')
        lines=text.splitlines(); i=0; first=True
        while i < len(lines):
            st=lines[i].strip(); i+=1
            if not st: continue
            if st.startswith('# '):
                cmd='\\chapter' if ch.get('book_class',True) else '\\section'
                if not ch.get('numbered',True): cmd+='*'
                out.append(f"{cmd}{{{latex_escape(st[2:].strip())}}}")
            elif st.startswith('## '): out.append(f"\\section{{{latex_escape(st[3:].strip())}}}")
            elif st.startswith('- '): out.append('\\begin{itemize}\n\\item '+latex_escape(st[2:].strip())+'\n\\end{itemize}')
            else: out.append(latex_escape(st)+'\n')
    return '\n\n'.join(out)

