    cls='article' if article else option(book,'tex.class','book') or 'book'
    title=latex_escape(option(book,'title','')); author=latex_escape(option(book,'author','')); lang=option(book,'lang','en') or 'en'
    babel='english' if lang.startswith('en') else ('french' if lang.startswith('fr') else lang)
    for ch in book.chapters: ch['book_class']=not article
    body=md_to_tex_body(book.chapters)
    return f'''\\documentclass{{{cls}}}

