                write_output(render_html(b), out, False)
                if out and out!='-': infos.append(f"Succesfully generated HTML (standalone page): {out}")
            elif fmt=='tex':
                out=output_target(b,'tex',opts)
                write_output(render_tex(b, article=opts.single), out, False)
                if out and out!='-': infos.append(f"Succesfully generated LaTeX: {out}")
            elif fmt=='epub':
                out=output_target(b,'epub',opts)
                write_output(render_epub_bytes(b), out, True)
                warnings.append('Could not run zip command, falling back to zip library')
                if out and out!='-': infos.append(f"Succesfully generated EPUB: {out}")
            elif fmt=='pdf':
                errors.append("Error during temporary files editing: failed to run command 'xelatex'")
            elif fmt=='html.dir':
                out=output_target(b,'html.dir',opts)
                if not out:
                    errors.append('Error during rendering: can only render HTML directory to a path, not to a stream')
                else:
