                    for er in errors: eprint('ERROR '+er)
                else:
                    eprint('WARNING Crowbook exited successfully, but the following errors occurred:')
                    for er in errors: eprint('ERROR '+er)
                    for w in warnings: eprint('WARNING '+w)
    return 0

def do_print_template(opts):
    banner(opts)
    name=opts.print_template
    p=data_path('templates', name)
    if p.exists() and p.is_file():
        sys.stdout.buffer.write(p.read_bytes())
    else:
        if not opts.quiet: eprint(f"ERROR {name} is not a valid template name")
    return 0

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    opts,code=parse_args(argv)
    if code is not None: return code
    if opts.create is not None: return do_create(opts)
    if opts.list_options:
        banner(opts)
        try: sys.stdout.write(read_text_file(data_path('list_options.txt')))
        except Exception: pass
        return 0
    if opts.print_template is not None: return do_print_template(opts)
    return run_render(opts)

if __name__ == '__main__':
    sys.exit(main())
