def latex_escape(s):
    return s.replace('\\','\\textbackslash{}').replace('&','\\&').replace('%','\\%').replace('$','\\$').replace('#','\\#').replace('_','\\_').replace('{','\\{').replace('}','\\}')

def md_to_tex_body(chapters):
    out=[]
    for ch in chapters:
        text=ch.get('content','')
        lines=text.splitlines(); i=0; first=True
        while i < len(lines):
            st=lines[i].strip(); i+=1
            if not st: continue
            if st.startswith('# '):
                cmd='\\chapter' if ch.get('book_class',True) else '\\section'
                if not ch.get('numbered',True): cmd+='*'
                out.append(f"{cmd}{{{latex_escape(st[2:].strip())}}}")
            elif st.startswith('## '): out.append(f"\\section{{{latex_escape(st[3:].strip())}}}")
            elif st.startswith('- '): out.append('\\begin{itemize}\n\\item '+latex_escape(st[2:].strip())+'\n\\end{itemize}')
            else: out.append(latex_escape(st)+'\n')
    return '\n\n'.join(out)

def render_tex(book, article=False):
    cls='article' if article else option(book,'tex.class','book') or 'book'
    title=latex_escape(option(book,'title','')); author=latex_escape(option(book,'author','')); lang=option(book,'lang','en') or 'en'
    babel='english' if lang.startswith('en') else ('french' if lang.startswith('fr') else lang)
    for ch in book.chapters: ch['book_class']=not article
    body=md_to_tex_body(book.chapters)
    return f'''\\documentclass{{{cls}}}

%% Package inclusion

% Unicode support if xelatex is used
\\usepackage{{fontspec}}
\\usepackage{{xunicode}}


\\usepackage[{babel}]{{babel}} % Language support
\\usepackage{{fancyhdr}} % Headers
\\usepackage{{enumitem}}

% Allows hyphenatations in \\texttt
\\usepackage[htt]{{hyphenat}}


% Set hyperlinks and metadata
\\usepackage[colorlinks=true,breaklinks=true,hypertexnames=false]{{hyperref}}
\\hypersetup{{pdfauthor={{{author}}},
  pdftitle={{{title}}},
  pdfsubject={{}}
}}

\\usepackage[a5paper, top=2cm, bottom=1.5cm,
  left=2.5cm,right=1.5cm]{{geometry}} % Set dimensions/margins of the page

\\title{{{title}}}
\\author{{{author}}}

\\begin{{document}}
\\maketitle

{body}

\\end{{document}}
'''

def render_epub_bytes(book):
    html_content,titles=all_chapters_html(book)
    title=html.escape(option(book,'title',''), quote=False); author=html.escape(option(book,'author',''), quote=False); lang=option(book,'lang','en') or 'en'
    css='body { font-family: serif; }\np { text-indent: 1.25em; }\n'
    try: css=read_text_file(data_path('templates','epub.css'))
    except Exception: pass
    chapter=f'''<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml" xml:lang="{lang}" lang="{lang}"><head><title>{title}</title><link rel="stylesheet" type="text/css" href="stylesheet.css" /></head><body><div id="page">{html_content}</div></body></html>'''
    titlepage=f'''<?xml version="1.0" encoding="UTF-8"?><html xmlns="http://www.w3.org/1999/xhtml"><head><title>{title}</title></head><body><h1>{title}</h1><h2>{author}</h2></body></html>'''
    opf=f'''<?xml version="1.0" encoding="utf-8"?><package version="2.0" xmlns="http://www.idpf.org/2007/opf"><metadata><dc:title xmlns:dc="http://purl.org/dc/elements/1.1/">{title}</dc:title><dc:creator xmlns:dc="http://purl.org/dc/elements/1.1/">{author}</dc:creator><dc:language xmlns:dc="http://purl.org/dc/elements/1.1/">{lang}</dc:language></metadata><manifest><item id="chapter" href="chapter_000.xhtml" media-type="application/xhtml+xml"/><item id="style" href="stylesheet.css" media-type="text/css"/></manifest><spine><itemref idref="chapter"/></spine></package>'''
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,'w',compression=zipfile.ZIP_DEFLATED) as z:
        z.writestr('mimetype','application/epub+zip',compress_type=zipfile.ZIP_STORED)
        z.writestr('META-INF/container.xml','''<?xml version="1.0"?><container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles></container>''')
        z.writestr('OEBPS/title_page.xhtml',titlepage)
        z.writestr('OEBPS/chapter_000.xhtml',chapter)
        z.writestr('OEBPS/stylesheet.css',css)
        z.writestr('OEBPS/content.opf',opf)
        z.writestr('OEBPS/toc.ncx','')
        z.writestr('OEBPS/nav.xhtml','')
    return bio.getvalue()

def write_output(data, out, binary=False):
    if out is None or out == '-':
        if binary:
            sys.stdout.buffer.write(data)
        else:
            sys.stdout.write(data)
    else:
        mode='wb' if binary else 'w'
        kwargs={} if binary else {'encoding':'utf-8'}
        with open(out, mode, **kwargs) as f: f.write(data)

def render_html_dir(book, outdir):
    if not outdir or outdir=='-':
        raise ValueError('stream')
    os.makedirs(outdir, exist_ok=True)
    css=read_text_file(data_path('templates','html.css')) if data_path('templates','html.css').exists() else 'body{}'
    Path(outdir,'stylesheet.css').write_text(css,encoding='utf-8')
    Path(outdir,'print.css').write_text('#page { }\n',encoding='utf-8')
    content,titles=all_chapters_html(book)
    title=option(book,'title','')
    Path(outdir,'chapter_000.html').write_text(f'<!DOCTYPE html>\n<html><head><title>{html.escape(title)}</title><link rel="stylesheet" href="stylesheet.css" /></head><body>{content}</body></html>\n',encoding='utf-8')

def output_target(book, fmt, opts):
    if opts.output: return opts.output
    key={'html':'output.html','epub':'output.epub','tex':'output.tex','pdf':'output.pdf','html.dir':'output.html.dir'}.get(fmt)
    if key and key in book.options: return book.options[key]
    return None

def parse_output_list(v):
    v=v.strip()
    if v.startswith('[') and v.endswith(']'): v=v[1:-1]
    return [x.strip().strip('"\'') for x in re.split(r'[,\s]+', v) if x.strip().strip(',')]

def do_stats(book):
    rows=[]; total_chars=0; total_words=0
    for ch in book.chapters:
        text=ch.get('content','')
        clean=[]
        for line in text.splitlines():
            s=line.strip()
            if s.startswith('#'): s=s.lstrip('#').strip()
            clean.append(s)
        joined='\n'.join(clean).strip()
        chars=len(joined); words=len(re.findall(r'\b\S+\b', joined))
        total_chars+=chars; total_words+=words
        rows.append((ch.get('file',''), chars, words, (chars/words if words else 0)))
    print('Chapter     Chars      Words  Chars/Word')
    print('---------')
    for name,chars,words,ratio in rows:
        print(f"{name:<10}{chars:>7}{words:>11}{ratio:>12.2f}")
    print('---------')
    ratio=total_chars/total_words if total_words else 0
    print(f"TOTAL:{total_chars:>10}{total_words:>11}{ratio:>12.2f}")
    print()

def run_render(opts):
    if not opts.book:
        banner(opts)
        if not opts.quiet:
            eprint('ERROR You must pass the name of a book configuration file.')
            eprint('For more information try --help.')
            eprint('')
        return 0
    b=parse_book_file(opts.book, opts.single)
    apply_sets(b, opts.sets)
    # Plain markdown without --single: mimic friendly parse error if no book-ish lines
    if (not opts.single) and b.errors:
        banner(opts)
        if not opts.quiet:
            for _,msg in b.errors: eprint('ERROR '+msg.rstrip('\n'))
        return 0
    if b.path and not Path(opts.book).exists():
        banner(opts)
        if not opts.quiet: eprint(f"ERROR Could not find file '{opts.book}' for book")
        return 0
    banner(opts)
    if b.errors:
        if not opts.quiet:
            for _,msg in b.errors: eprint('ERROR '+msg.rstrip('\n'))
        return 0
    if opts.stats:
        do_stats(b); return 0
    # invalid option warnings do not stop rendering in the real app, but are displayed as accumulated errors
    formats=[]
    if opts.to:
        formats=[opts.to]
    elif opts.single:
        # only render configured outputs in single mode
        for fmt,key in [('html','output.html'),('epub','output.epub'),('tex','output.tex'),('pdf','output.pdf'),('html.dir','output.html.dir')]:
            if key in b.options: formats.append(fmt)
    else:
        if 'output' in b.options: formats.extend(parse_output_list(b.options['output']))
        for fmt,key in [('tex','output.tex'),('html','output.html'),('epub','output.epub'),('pdf','output.pdf'),('html.dir','output.html.dir')]:
            if key in b.options and fmt not in formats: formats.append(fmt)
    warnings=[]; errors=[]; infos=[]
    if b.warnings:
        errors.extend(b.warnings)
    for fmt in formats:
        try:
            if fmt=='html':
                out=output_target(b,'html',opts)
                write_output(render_html(b), out, False)
                if out and out!='-': infos.append(f"Succesfully generated HTML (standalone page): {out}")
            elif fmt=='tex':
                out=output_target(b,'tex',opts)
                write_output(render_tex(b, article=opts.single), out, False)
                if out and out!='-': infos.append(f"Succesfully generated LaTeX: {out}")
            elif fmt=='epub':
                out=output_target(b,'epub',opts)
                write_output(render_epub_bytes(b), out, True)
                warnings.append('Could not run zip command, falling back to zip library')
                if out and out!='-': infos.append(f"Succesfully generated EPUB: {out}")
            elif fmt=='pdf':
                errors.append("Error during temporary files editing: failed to run command 'xelatex'")
            elif fmt=='html.dir':
                out=output_target(b,'html.dir',opts)
                if not out:
                    errors.append('Error during rendering: can only render HTML directory to a path, not to a stream')
                else:
                    render_html_dir(b,out); errors.append('Error compiling template: render error')
            else:
                errors.append(f'unknown format {fmt}')
        except Exception as ex:
            errors.append(str(ex))
    if not opts.quiet:
        if opts.no_fancy:
            for w in warnings: eprint('[WARN] '+w)
            for er in errors: eprint('[ERROR] '+er)
            for inf in infos: eprint('[INFO] '+inf)
        else:
            if warnings or errors:
                # For a sole fatal error, real Crowbook usually prints ERROR directly; for successful render with warnings it summarizes.
                if warnings and not errors:
                    eprint('WARNING Crowbook exited successfully, but the following errors occurred:')
                    for w in warnings: eprint('WARNING '+w)
                elif errors and not formats:
                    for er in errors: eprint('ERROR '+er)
                elif errors and not warnings and len(formats)==1 and formats[0] in ('pdf','odt','html.dir'):
                    for er in errors: eprint('ERROR '+er)
                else:
                    eprint('WARNING Crowbook exited successfully, but the following errors occurred:')
                    for er in errors: eprint('ERROR '+er)
                    for w in warnings: eprint('WARNING '+w)
    return 0

def do_print_template(opts):
    banner(opts)
    name=opts.print_template
    p=data_path('templates', name)
    if p.exists() and p.is_file():
        sys.stdout.buffer.write(p.read_bytes())
    else:
        if not opts.quiet: eprint(f"ERROR {name} is not a valid template name")
    return 0

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    opts,code=parse_args(argv)
    if code is not None: return code
    if opts.create is not None: return do_create(opts)
    if opts.list_options:
        banner(opts)
        try: sys.stdout.write(read_text_file(data_path('list_options.txt')))
        except Exception: pass
        return 0
    if opts.print_template is not None: return do_print_template(opts)
    return run_render(opts)

if __name__ == '__main__':
    sys.exit(main())
